sp_widget.client_script:
api.controller = function() {

    var c = this;


    /*
     * ============================================================
     * VARIABLES
     * ============================================================
     */

    c.search = '';

    c.statusFilter = 'all';

    c.selectedStudent = null;


    /*
     * ============================================================
     * FILTER STUDENTS
     * ============================================================
     */

    c.getFilteredStudents = function() {

        var students =
            c.data.students || [];

        var results = [];

        var searchText =
            String(c.search || '')
            .toLowerCase()
            .trim();


        for (var i = 0; i < students.length; i++) {

            var student =
                students[i];


            /*
             * ----------------------------------------------------
             * SEARCH
             * ----------------------------------------------------
             */

            var searchableText =
                String(student.name || '') + ' ' +
                String(student.id || '') + ' ' +
                String(student.branch || '') + ' ' +
                String(student.degree || '') + ' ' +
                String(student.email || '');

            searchableText =
                searchableText.toLowerCase();


            if (
                searchText &&
                searchableText.indexOf(searchText) === -1
            ) {

                continue;

            }


            /*
             * ----------------------------------------------------
             * PROFILE STATUS FILTER
             * ----------------------------------------------------
             */

            if (
                c.statusFilter === 'active' &&
                String(student.profileStatus).toLowerCase() !==
                'active'
            ) {

                continue;

            }


            if (
                c.statusFilter === 'inactive' &&
                String(student.profileStatus).toLowerCase() !==
                'inactive'
            ) {

                continue;

            }


            results.push(student);

        }


        return results;

    };


    /*
     * ============================================================
     * OPEN STUDENT
     * ============================================================
     */

    c.openStudent = function(student) {

        if (!student) {
            return;
        }

        c.selectedStudent =
            student;

    };


    /*
     * ============================================================
     * CLOSE STUDENT
     * ============================================================
     */

    c.closeStudent = function() {

        c.selectedStudent =
            null;

    };


    /*
     * ============================================================
     * ADD STUDENT
     * ============================================================
     *
     * Opens a new record in the Campus360 Student Master table.
     *
     * ============================================================
     */

    c.addStudent = function() {

        window.location.href =
            '/x_snc_campus360_student_master.do?sys_id=-1';

    };


    /*
     * ============================================================
     * OPEN FULL STUDENT RECORD
     * ============================================================
     */

    c.viewRecord = function(student) {

        if (!student || !student.sys_id) {
            return;
        }


        window.location.href =
            '/x_snc_campus360_student_master.do?sys_id=' +
            encodeURIComponent(student.sys_id);

    };


    /*
     * ============================================================
     * REFRESH
     * ============================================================
     */

    c.refresh = function() {

        c.server.refresh();

    };


    /*
     * ============================================================
     * INITIAL STATE
     * ============================================================
     */

    c.getFilteredStudents();

};

sp_widget.css:
/* ==========================================================================
