   ========================================================================== */

html, body, #sp-page, .sp-page-container, #page_content, .page, main {
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  background-color: #f8fafc !important;
}

/* HIDE SERVICENOW TOP BANNER & NAVBAR FOR ALL TPO PAGE ROOT CONTAINERS */
