  margin: 0 auto;
  color: #18233f;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.page-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 28px;
}

.eyebrow,
.card-eyebrow {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.4px;
  color: #6941d9;
  margin-bottom: 6px;
}

.page-header h1 {
  margin: 0;
  font-size: 32px;
  font-weight: 800;
  color: #111b38;
}

.page-header p {
  margin: 7px 0 0;
  color: #71809c;
  font-size: 14px;
}

.primary-btn {
  border: 0;
  border-radius: 12px;
  padding: 12px 18px;
  background: #6338d8;
  color: #fff;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 7px 18px rgba(99, 56, 216, .22);
  transition: .2s;
}

.primary-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 24px rgba(99, 56, 216, .28);
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}

.summary-card {
  min-height: 92px;
  border: 1px solid #e4e9f3;
  border-radius: 16px;
  padding: 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  background: #fff;
  transition: .2s;
}

.summary-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 28px rgba(35, 50, 90, .08);
}

.summary-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  font-weight: 800;
}

.summary-card span {
  display: block;
  font-size: 12px;
  color: #7886a0;
  margin-bottom: 4px;
}

.summary-card strong {
  font-size: 25px;
  color: #18233f;
}

.blue .summary-icon {
  background: #eaf3ff;
  color: #2874e6;
}

.green .summary-icon {
  background: #e7f9ef;
  color: #159957;
}

.purple .summary-icon {
  background: #f0eaff;
  color: #6941d9;
}

.red .summary-icon {
  background: #fff0f1;
  color: #df3148;
}

.toolbar {
  display: flex;
  gap: 12px;
  margin-bottom: 18px;
}

.search-box {
  flex: 1;
  height: 44px;
  border: 1px solid #dfe5f0;
  background: #fff;
  border-radius: 11px;
  display: flex;
  align-items: center;
  padding: 0 14px;
}

.search-box span {
  font-size: 21px;
  color: #8a96aa;
  margin-right: 9px;
}

.search-box input {
  border: 0;
  outline: 0;
  width: 100%;
  font-size: 13px;
  color: #283550;
}

.toolbar select {
  min-width: 150px;
  border: 1px solid #dfe5f0;
  border-radius: 11px;
  padding: 0 13px;
  background: #fff;
  color: #394662;
}

.refresh-btn {
  width: 44px;
  border: 1px solid #dfe5f0;
  background: #fff;
  border-radius: 11px;
  font-size: 19px;
  cursor: pointer;
}

.refresh-btn:hover {
  background: #f6f3ff;
}

.student-card {
  background: #fff;
  border: 1px solid #e2e7f0;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 4px 18px rgba(35, 50, 90, .04);
}

.card-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 24px;
  border-bottom: 1px solid #edf0f5;
}

.card-heading h2 {
  margin: 0;
  font-size: 19px;
  color: #17213d;
}

.record-count {
  font-size: 12px;
  color: #75829a;
  background: #f4f6fb;
  padding: 7px 11px;
  border-radius: 20px;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead {
  background: #fafbfe;
}

th {
  padding: 13px 18px;
  text-align: left;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .6px;
  color: #8290a9;
  font-weight: 800;
}

td {
  padding: 15px 18px;
  border-top: 1px solid #edf0f5;
  font-size: 13px;
  color: #48556e;
}

.student-row {
  cursor: pointer;
  transition: .15s;
}

.student-row:hover {
  background: #faf8ff;
}

.student-cell {
  display: flex;
  align-items: center;
  gap: 11px;
}

.avatar,
.modal-avatar {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: #eee8ff;
  color: #6639d7;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.student-cell strong {
  display: block;
  color: #1d2944;
  font-size: 13px;
}

.student-cell span {
  display: block;
  color: #8a96aa;
  font-size: 11px;
  margin-top: 2px;
}

.student-id {
  font-family: monospace;
  font-size: 12px;
  color: #66738d;
}

.cgpa {
  color: #253252;
}

.backlog-badge,
.status-badge,
.profile-badge {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
}

.backlog-clear {
  background: #eaf8ef;
  color: #16864c;
}

.backlog-warning {
  background: #fff1df;
  color: #c56a00;
}

.status-placed {
  background: #e6f8ee;
  color: #16894d;
}

.status-active {
  background: #edf3ff;
  color: #316ed3;
}

.profile-active {
  background: #eeeaff;
  color: #6742d5;
}

.profile-inactive {
  background: #f0f2f6;
  color: #7d8799;
}

.view-btn {
  border: 0;
  background: transparent;
  color: #6036d2;
  font-weight: 700;
  cursor: pointer;
}

.view-btn:hover {
  text-decoration: underline;
}

.empty-state {
  text-align: center;
  padding: 55px 20px;
}

.empty-icon {
  font-size: 35px;
  color: #8b7ae6;
}

.empty-state h3 {
  margin: 12px 0 4px;
  color: #26324d;
}

.empty-state p {
  margin: 0;
  color: #8994a9;
}

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(20, 28, 48, .45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
}

.student-modal {
  width: 720px;
  max-width: 100%;
  background: #fff;
  border-radius: 20px;
  padding: 28px;
  position: relative;
  box-shadow: 0 25px 70px rgba(15, 25, 50, .2);
}

.modal-close {
  position: absolute;
  right: 18px;
  top: 15px;
  border: 0;
  background: transparent;
  font-size: 27px;
  color: #8994a9;
  cursor: pointer;
}

.modal-profile {
  display: flex;
  align-items: center;
  gap: 15px;
  padding-bottom: 22px;
  border-bottom: 1px solid #edf0f5;
}

.modal-avatar {
  width: 55px;
  height: 55px;
  border-radius: 15px;
  font-size: 17px;
}

.modal-profile h2 {
  margin: 0 0 3px;
  color: #17213d;
}

.modal-profile span {
  color: #8490a5;
  font-size: 12px;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  padding: 24px 0;
}

.detail-grid span {
  display: block;
  color: #8a96aa;
  font-size: 11px;
  text-transform: uppercase;
  margin-bottom: 5px;
}

.detail-grid strong {
  color: #293650;
  font-size: 13px;
}

.modal-actions {
  border-top: 1px solid #edf0f5;
  padding-top: 20px;
}

.secondary-btn {
  border: 1px solid #d9d0f7;
  background: #f7f4ff;
  color: #6137cf;
  padding: 10px 15px;
  border-radius: 10px;
  font-weight: 700;
  cursor: pointer;
}

@media (max-width: 900px) {
  .summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .campus360-tpo-page {
    padding: 20px;
  }
}

@media (max-width: 600px) {
  .summary-grid {
    grid-template-columns: 1fr;
  }

  .page-header {
    display: block;
  }

  .primary-btn {
    margin-top: 15px;
  }

  .toolbar {
    flex-wrap: wrap;
  }

  .search-box {
    flex-basis: 100%;
  }
}
.campus360-tpo-layout,
.tpo-layout,
.tpo-container,
.campus360-skill-intel,
.tpo-dashboard-center {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  z-index: 9999 !important;
  overflow: hidden !important;
  background: #f8fafc !important;
}

.campus360-tpo-layout,
.tpo-layout,
.tpo-container,
.campus360-skill-intel,
.tpo-dashboard-center {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  z-index: 9999 !important;
  overflow: hidden !important;
  background: #f8fafc !important;
}

sp_widget.script:
(function() {
  try { data.chatbotWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {}); } catch(e) {}

    /*
     * ============================================================
     * CAMPUS360 TPO STUDENTS
     * Server-side data provider
     * ============================================================
     */

    data.students = [];
    data.stats = {
        total: 0,
        placed: 0,
        active: 0,
        highRisk: 0
    };


    /*
     * ============================================================
     * STUDENT MASTER
     * ============================================================
     */

    var studentGR = new GlideRecordSecure(
        'x_snc_campus360_student_master'
    );

    studentGR.orderBy('student_name');
    studentGR.query();


    while (studentGR.next()) {

        var studentName =
            studentGR.getValue('student_name') || 'Unnamed Student';

        var initials = getInitials(studentName);

        var placementStatus =
            studentGR.getDisplayValue('placement_status') ||
            studentGR.getValue('placement_status') ||
            'Not Placed';

        var profileStatus =
            studentGR.getDisplayValue('profile_status') ||
            studentGR.getValue('profile_status') ||
            '';


        var student = {

            sys_id:
                studentGR.getUniqueValue(),

            id:
                studentGR.getValue('student_id') || '',

            name:
                studentName,

            initials:
                initials,

            email:
                studentGR.getValue('email') || '',

            phone:
                studentGR.getValue('phone_number') || '',

            batch:
                studentGR.getValue('batch') || '',

            degree:
                studentGR.getValue('degree') || '',

            branch:
                studentGR.getValue('branch') || '',

            cgpa:
                studentGR.getValue('cgpa') || '',

            backlogs:
                parseInt(
                    studentGR.getValue('backlogs'),
                    10
                ) || 0,

            placementStatus:
                placementStatus,

            profileStatus:
                profileStatus

        };


        data.students.push(student);

    }


    /*
     * ============================================================
     * BASIC STATISTICS
     * ============================================================
     */

    data.stats.total =
        data.students.length;


    for (var i = 0; i < data.students.length; i++) {

        var s =
            data.students[i];


        if (
            String(s.placementStatus).toLowerCase() ===
            'placed'
        ) {

            data.stats.placed++;

        }


        if (
            String(s.profileStatus).toLowerCase() ===
            'active'
        ) {

            data.stats.active++;

        }

    }


    /*
     * ============================================================
     * HIGH-RISK STUDENTS
     *
     * Based on Placement Intelligence records.
     * ============================================================
     */

    var intelligenceGR = new GlideRecordSecure(
        'x_snc_campus360_placement_intelligence'
    );

    intelligenceGR.addQuery(
        'risk_level',
        'High'
    );

    intelligenceGR.query();

    data.stats.highRisk =
        intelligenceGR.getRowCount();


    /*
     * ============================================================
     * ADD STUDENT ACTION
     * ============================================================
     *
     * The actual navigation is handled by the client controller.
     *
     * ============================================================
     */


    /*
     * ============================================================
     * HELPER
     * ============================================================
     */

    function getInitials(name) {

        if (!name) {
            return '?';
        }

        var parts =
            String(name).trim().split(/\s+/);

        if (parts.length === 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }

        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    }

})();

try {
  data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {});
  data.chatbotWidget = data.aiWidget;
} catch(e) {}
